import subprocess, re, collections

def sh(cmd):
    return subprocess.run(cmd, shell=True, capture_output=True, text=True).stdout

branches = ['rachel', 'monica', 'phoebe', 'joey', 'chandler', 'ross']
src = {}
for b in branches:
    log = sh(f"git log --format=%H%x1f%B%x1e origin/friend/{b}")
    for rec in log.split('\x1e'):
        if not rec.strip():
            continue
        p = rec.split('\x1f', 1)
        if len(p) < 2:
            continue
        sha, body = p[0].strip(), p[1]
        if 'Friend-Message: 1' not in body:
            continue
        i = body.find('Reply-To:')
        j = body.find('\n\n', i)
        ut = body[j + 2:].strip() if j >= 0 else ''
        src[sha] = ut

files = [f for f in sh("git ls-tree -r --name-only origin/main").split()
         if re.match(r'^S\d\d/E\d\d\.md$', f)]
checked = 0
bad = 0
for f in sorted(files):
    txt = sh(f"git show origin/main:{f}")
    cur = None
    entries = []
    for line in txt.split('\n'):
        m = re.match(r'^\*\*(\w+)\*\* \((.+)\)\s*$', line)
        if m:
            if cur:
                entries.append(cur)
            cur = {'speaker': m.group(1), 'ts': m.group(2), 'src': None, 'text': []}
            continue
        if cur is None:
            continue
        ms = re.match(r'^Source: (\S+) @ ([0-9a-f]{40})\s*$', line)
        if ms and cur['src'] is None:
            cur['src'] = ms.group(2)
            continue
        cur['text'].append(line)
    if cur:
        entries.append(cur)
    for e in entries:
        if not e['src']:
            continue
        checked += 1
        filed = '\n'.join(e['text']).strip()
        expected = src.get(e['src'])
        if expected is None:
            print(f"UNKNOWN SOURCE {f} {e['src']}")
            bad += 1
        elif filed != expected:
            print(f"MISMATCH {f} {e['src']}\n  branch: {expected!r}\n  filed : {filed!r}")
            bad += 1
print(f"checked={checked} mismatches={bad}")
